const fs = await import('node:fs');
const path = await import('node:path');
const inputPath = process.env.INPUT_PATH;
const outputPath = process.env.OUTPUT_PATH;
if (!inputPath) throw new Error('INPUT_PATH is required');
if (!outputPath) throw new Error('OUTPUT_PATH is required');
if (!fs.existsSync(inputPath)) throw new Error('Input CSV file not found: ' + inputPath);
fs.mkdirSync(path.dirname(outputPath) || '.', { recursive: true });
globalThis.csvInputPath = inputPath;
globalThis.csvOutputPath = outputPath;

const fs = await import('node:fs');
const csvToMarkdown = (await import('csv-to-markdown-table')).default;
if (typeof csvToMarkdown !== 'function') throw new Error('csv-to-markdown-table default export is not a function');
const csv = fs.readFileSync(globalThis.csvInputPath, 'utf8');
const markdown = csvToMarkdown(csv, ',', true);
if (typeof markdown !== 'string' || markdown.trim().length === 0) throw new Error('CSV to Markdown conversion produced empty output');
fs.writeFileSync(globalThis.csvOutputPath, markdown, 'utf8');
globalThis.csvMarkdown = markdown;
